import Link from "next/link";
import { helpSections } from "./constants";
import { ArrowUpRight, MessageCircle, Phone, Mail } from "lucide-react";
import { IoIosArrowDown } from "react-icons/io";

export default function HelpHub() {
  return (
    <div className="animate-in fade-in duration-1000">
      {/* 1. HERO SECTION */}
      <section className="h-screen flex justify-center items-center px-6 border-b border-border">
        <div className="max-w-7xl mx-auto text-center">
          <h2 className="text-7xl md:text-[10rem] font-black uppercase tracking-tighter leading-[0.8] italic">
            How can we{" "}
            <span className="text-foreground-subtle">Help?</span>
          </h2>
          <p className="text-xl text-foreground-muted max-w-xl mx-auto">
            Our support team and resources are available 24/7 to ensure your
            experience is seamless.
          </p>
        </div>

        <div className="absolute bottom-30 left-1/2 transform -translate-x-1/2 animate-bounce">
          <IoIosArrowDown size={32} className="text-foreground-muted" />
        </div>
      </section>

      {/* 2. LIVE SUPPORT GRID (WhatsApp & Chat) */}
      <section className="grid grid-cols-1 md:grid-cols-2 border-b border-border h-auto md:h-64">
        <a
          href="https://wa.me/yournumber"
          className="group p-12 flex items-center justify-between hover:bg-[#25D366] transition-all duration-500"
        >
          <div className="flex items-center gap-6">
            <div className="p-4 bg-background-muted rounded-full group-hover:bg-white/20">
              <MessageCircle className="group-hover:text-white" size={32} />
            </div>
            <div>
              <h3 className="text-3xl font-black uppercase group-hover:text-white">
                WhatsApp Support
              </h3>
              <p className="text-foreground-muted group-hover:text-white/80">
                Average response: 5 mins
              </p>
            </div>
          </div>
          <ArrowUpRight className="group-hover:text-white" size={32} />
        </a>
        <button className="group p-12 flex items-center justify-between hover:bg-brand transition-all duration-500 border-t md:border-t-0 md:border-l border-border">
          <div className="flex items-center gap-6">
            <div className="p-4 bg-background-muted rounded-full group-hover:bg-white/20">
              <Phone className="group-hover:text-white" size={32} />
            </div>
            <div>
              <h3 className="text-3xl font-black uppercase group-hover:text-white">
                Live Concierge
              </h3>
              <p className="text-foreground-muted group-hover:text-white/80">
                Available Mon-Fri
              </p>
            </div>
          </div>
          <ArrowUpRight className="group-hover:text-white" size={32} />
        </button>
      </section>

      {/* 3. EDITORIAL POLICY GRID */}
      <section className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
        {helpSections.map((item, index) => (
          <Link
            key={item.id}
            href={item.href}
            className={`group relative p-12 h-80 flex flex-col justify-between border-border transition-all duration-700 hover:bg-foreground 
              ${index % 3 !== 2 ? "lg:border-r" : ""} ${
              index < 6 ? "border-b" : ""
            }
            `}
          >
            <div className="flex justify-between items-start">
              <div className="p-4 bg-background-muted rounded-2xl group-hover:bg-background group-hover:text-foreground">
                {item.icon}
              </div>
              <ArrowUpRight
                className="opacity-0 group-hover:opacity-100 transition-all text-background"
                size={24}
              />
            </div>
            <div>
              <p className="text-[10px] font-black uppercase tracking-widest text-brand mb-2 italic">
                Ref. FF-0{index + 1}
              </p>
              <h3 className="text-4xl font-black uppercase tracking-tighter group-hover:text-background leading-none transition-colors">
                {item.label}
              </h3>
              <p className="text-sm text-foreground-subtle mt-2 group-hover:text-background/60 transition-colors">
                {item.tagline}
              </p>
            </div>
          </Link>
        ))}
      </section>
    </div>
  );
}
